#!/usr/bin/env python3
"""CLI tool for batch image processing: resize, crop, convert, watermark."""

import os
import sys
from pathlib import Path

import click
from PIL import Image, ImageDraw, ImageFont


def collect_inputs(sources: tuple[str, ...]) -> list[Path]:
    """Expand inputs into a flat list of image files."""
    files = []
    for src in sources:
        p = Path(src)
        if p.is_dir():
            files.extend(sorted(p.iterdir()))
        elif p.is_file():
            files.append(p)
        else:
            click.echo(f"Warning: skipping {src} (not found)", err=True)
    return [f for f in files if f.suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tiff", ".webp"}]


def make_output_path(src: Path, output_dir: str | None, suffix: str, ext: str | None) -> Path:
    """Build the output file path."""
    new_ext = (ext or src.suffix).lstrip(".")
    name = f"{src.stem}{suffix}.{new_ext}"
    if output_dir:
        os.makedirs(output_dir, exist_ok=True)
        return Path(output_dir) / name
    return src.parent / name


def save_image(img: Image.Image, path: Path, quality: int):
    """Save an image, respecting format-specific options."""
    kwargs = {}
    fmt = path.suffix.lower().lstrip(".")
    if fmt in ("jpg", "jpeg"):
        kwargs["quality"] = quality
        kwargs["optimize"] = True
        img = img.convert("RGB")
    elif fmt == "webp":
        kwargs["quality"] = quality
    img.save(path, **kwargs)


@click.group()
@click.version_option(version="1.0.0")
def cli():
    """Image processing CLI — resize, crop, convert, watermark."""


# ---------------------------------------------------------------------------
# Resize
# ---------------------------------------------------------------------------
@cli.command()
@click.argument("sources", nargs=-1, required=True, type=click.Path(exists=True))
@click.option("-W", "--width", type=int, help="Target width (px).")
@click.option("-H", "--height", type=int, help="Target height (px).")
@click.option("-s", "--scale", type=float, help="Scale factor (e.g. 0.5 for 50%).")
@click.option("--keep-aspect", is_flag=True, default=True, help="Preserve aspect ratio (default).")
@click.option("-o", "--output-dir", type=click.Path(), help="Output directory.")
@click.option("-e", "--ext", help="Output format extension (e.g. png, webp).")
@click.option("-q", "--quality", default=85, show_default=True, help="JPEG/WebP quality (1-100).")
@click.option("--suffix", default="_resized", show_default=True, help="Filename suffix.")
def resize(sources, width, height, scale, keep_aspect, output_dir, ext, quality, suffix):
    """Resize images to given dimensions or scale."""
    if not width and not height and not scale:
        click.echo("Error: provide --width, --height, or --scale", err=True)
        sys.exit(1)

    files = collect_inputs(sources)
    if not files:
        click.echo("No image files found.", err=True)
        sys.exit(1)

    for f in files:
        img = Image.open(f)
        if scale:
            new_w = int(img.width * scale)
            new_h = int(img.height * scale)
        elif keep_aspect and width and not height:
            ratio = width / img.width
            new_w, new_h = width, int(img.height * ratio)
        elif keep_aspect and height and not width:
            ratio = height / img.height
            new_w, new_h = int(img.width * ratio), height
        else:
            new_w = width or img.width
            new_h = height or img.height

        out = img.resize((new_w, new_h), Image.LANCZOS)
        dest = make_output_path(f, output_dir, suffix, ext)
        save_image(out, dest, quality)
        click.echo(f"  {f.name} -> {dest} ({new_w}x{new_h})")

    click.echo(f"Resized {len(files)} image(s).")


# ---------------------------------------------------------------------------
# Crop
# ---------------------------------------------------------------------------
@cli.command()
@click.argument("sources", nargs=-1, required=True, type=click.Path(exists=True))
@click.option("-x", type=int, required=True, help="Left x coordinate.")
@click.option("-y", type=int, required=True, help="Top y coordinate.")
@click.option("-W", "--width", type=int, required=True, help="Crop width.")
@click.option("-H", "--height", type=int, required=True, help="Crop height.")
@click.option("--center", is_flag=True, help="Treat x/y as center instead of top-left.")
@click.option("-o", "--output-dir", type=click.Path(), help="Output directory.")
@click.option("-e", "--ext", help="Output format extension.")
@click.option("-q", "--quality", default=85, show_default=True, help="JPEG/WebP quality.")
@click.option("--suffix", default="_cropped", show_default=True, help="Filename suffix.")
def crop(sources, x, y, width, height, center, output_dir, ext, quality, suffix):
    """Crop a region from images."""
    files = collect_inputs(sources)
    if not files:
        click.echo("No image files found.", err=True)
        sys.exit(1)

    for f in files:
        img = Image.open(f)
        if center:
            left = x - width // 2
            top = y - height // 2
        else:
            left, top = x, y
        box = (left, top, left + width, top + height)
        out = img.crop(box)
        dest = make_output_path(f, output_dir, suffix, ext)
        save_image(out, dest, quality)
        click.echo(f"  {f.name} -> {dest}")

    click.echo(f"Cropped {len(files)} image(s).")


# ---------------------------------------------------------------------------
# Convert
# ---------------------------------------------------------------------------
@cli.command()
@click.argument("sources", nargs=-1, required=True, type=click.Path(exists=True))
@click.option("-f", "--format", "fmt", required=True, help="Target format (png, jpg, webp, bmp, tiff).")
@click.option("-o", "--output-dir", type=click.Path(), help="Output directory.")
@click.option("-q", "--quality", default=85, show_default=True, help="JPEG/WebP quality.")
def convert(sources, fmt, output_dir, quality):
    """Convert images to a different format."""
    fmt = fmt.lower().lstrip(".")
    if fmt == "jpeg":
        fmt = "jpg"

    files = collect_inputs(sources)
    if not files:
        click.echo("No image files found.", err=True)
        sys.exit(1)

    for f in files:
        img = Image.open(f)
        if fmt in ("jpg", "bmp") and img.mode == "RGBA":
            img = img.convert("RGB")
        dest = make_output_path(f, output_dir, "", fmt)
        save_image(img, dest, quality)
        click.echo(f"  {f.name} -> {dest}")

    click.echo(f"Converted {len(files)} image(s) to .{fmt}.")


# ---------------------------------------------------------------------------
# Watermark
# ---------------------------------------------------------------------------
@cli.command()
@click.argument("sources", nargs=-1, required=True, type=click.Path(exists=True))
@click.option("-t", "--text", help="Text watermark.")
@click.option("-i", "--image", "wm_image", type=click.Path(exists=True), help="Image watermark (PNG with alpha).")
@click.option("--position", default="bottom-right",
              type=click.Choice(["top-left", "top-right", "bottom-left", "bottom-right", "center"]),
              show_default=True, help="Watermark placement.")
@click.option("--opacity", type=click.IntRange(0, 255), default=128, show_default=True,
              help="Text/image opacity (0=invisible, 255=solid).")
@click.option("--font-size", type=int, default=36, show_default=True, help="Text font size.")
@click.option("--color", default="white", show_default=True, help="Text color.")
@click.option("--padding", type=int, default=20, show_default=True, help="Padding from edges (px).")
@click.option("-o", "--output-dir", type=click.Path(), help="Output directory.")
@click.option("-e", "--ext", help="Output format extension.")
@click.option("-q", "--quality", default=85, show_default=True, help="JPEG/WebP quality.")
@click.option("--suffix", default="_wm", show_default=True, help="Filename suffix.")
def watermark(sources, text, wm_image, position, opacity, font_size, color, padding, output_dir, ext, quality, suffix):
    """Add a text or image watermark to images."""
    if not text and not wm_image:
        click.echo("Error: provide --text or --image", err=True)
        sys.exit(1)

    files = collect_inputs(sources)
    if not files:
        click.echo("No image files found.", err=True)
        sys.exit(1)

    for f in files:
        img = Image.open(f).convert("RGBA")
        overlay = Image.new("RGBA", img.size, (0, 0, 0, 0))

        if text:
            draw = ImageDraw.Draw(overlay)
            try:
                font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", font_size)
            except (OSError, IOError):
                font = ImageFont.load_default()
            bbox = draw.textbbox((0, 0), text, font=font)
            tw, th = bbox[2] - bbox[0], bbox[3] - bbox[1]
            pos = _calc_position(position, img.size, (tw, th), padding)
            draw.text(pos, text, font=font, fill=(*_parse_color(color), opacity))
        else:
            wm = Image.open(wm_image).convert("RGBA")
            if opacity < 255:
                alpha = wm.split()[3]
                alpha = alpha.point(lambda a: int(a * opacity / 255))
                wm.putalpha(alpha)
            pos = _calc_position(position, img.size, wm.size, padding)
            overlay.paste(wm, pos)

        result = Image.alpha_composite(img, overlay)
        dest = make_output_path(f, output_dir, suffix, ext)
        save_image(result, dest, quality)
        click.echo(f"  {f.name} -> {dest}")

    click.echo(f"Watermarked {len(files)} image(s).")


def _calc_position(anchor: str, canvas: tuple[int, int], item: tuple[int, int], pad: int) -> tuple[int, int]:
    """Compute top-left coordinates for placement."""
    cw, ch = canvas
    iw, ih = item
    positions = {
        "top-left":     (pad, pad),
        "top-right":    (cw - iw - pad, pad),
        "bottom-left":  (pad, ch - ih - pad),
        "bottom-right": (cw - iw - pad, ch - ih - pad),
        "center":       ((cw - iw) // 2, (ch - ih) // 2),
    }
    return positions[anchor]


def _parse_color(name: str) -> tuple[int, int, int]:
    """Parse a color name or hex string into RGB."""
    named = {
        "white": (255, 255, 255), "black": (0, 0, 0), "red": (255, 0, 0),
        "green": (0, 255, 0), "blue": (0, 0, 255), "yellow": (255, 255, 0),
        "gray": (128, 128, 128), "grey": (128, 128, 128),
    }
    if name.lower() in named:
        return named[name.lower()]
    if name.startswith("#") and len(name) == 7:
        return (int(name[1:3], 16), int(name[3:5], 16), int(name[5:7], 16))
    return (255, 255, 255)


if __name__ == "__main__":
    cli()
